 static Dictionary<string,string> Peer(string ip,string port,string kind,string network="udp"){return new Dictionary<string,string>{{"destinationIP",ip},{"destinationPort",port},{"event",kind},{"network",network}};}
 static void AutopauseChecks(){
  var tracker=new WardogsMatchTracker();var now=DateTime.UtcNow;
  Check(!WardogsMatchTracker.MatchPeer("85.236.98.104",443)&&!WardogsMatchTracker.MatchPeer("104.18.124.108",7777)&&!WardogsMatchTracker.MatchPeer("85.236.104.1",7777),"autopause ignores login HTTPS and unrelated networks");
  tracker.Observe(new[]{Peer("85.236.98.104","7777","opened","tcp")},now);Check(!tracker.InMatch(now.AddSeconds(3)),"TCP connection is not a match signal");
  tracker.Observe(new[]{Peer("85.236.98.104","7777","opened")},now);Check(!tracker.InMatch(now.AddSeconds(1))&&tracker.InMatch(now.AddSeconds(2)),"game UDP needs two seconds before pause");
  tracker.Observe(new[]{Peer("85.236.105.131","7777","opened"),Peer("85.236.98.104","7777","closed")},now.AddSeconds(3));Check(!tracker.InMatch(now.AddSeconds(4)),"outside-network peer does not hold pause after game connection closes");
  tracker.LogLine("LogNet: Welcomed by server (Level: Arena)");Check(tracker.InMatch(now),"game log confirms match independently of UDP metadata");
  tracker.LogLine("LogNet: DestroyNamedNetDriver GameNetDriver");Check(!tracker.InMatch(now),"return or GameNetDriver shutdown resumes profile");
  tracker.LogLine("LogNet: Join succeeded: Player");tracker.Reset();Check(!tracker.InMatch(now),"game process exit clears match state");
  var serializer=new System.Web.Script.Serialization.JavaScriptSerializer();var saved=serializer.Deserialize<RouteList>(serializer.Serialize(new RouteList{WardogsAutoPause=true,OriginalEngine=true}));Check(saved.WardogsAutoPause&&saved.OriginalEngine,"autopause and original-engine flags survive save/reload");
  Check(!new GameFlowObserver().IncludeClosedEvents,"ordinary process capture does not start recording close events");
 }
 static void EngineSplitChecks(ZapretRuntime runtime,List<ZapretStrategy> catalog,string root){
