  var p=new ZapretProfile{Name="mixed",Enabled=true,Settings=new ZapretSettings{Strategy=baseStrategy.Id}};
  var state=new ClientState{ZapretProfiles=new List<ZapretProfile>{p},ExcludedApplications=new List<string>()};
  var original=new RouteList{Name="original",Target="zapret",ZapretProfileId=p.Id,Text="game.example\n85.236.98.104/32",MatchMode="addresses",OriginalEngine=true,GameFilterUdp=true};
  var ordinary=new RouteList{Name="ours",Target="zapret",ZapretProfileId=p.Id,Text="app:Discord.exe\ndiscord.com",MatchMode="in-apps"};state.Lists.Add(original);state.Lists.Add(ordinary);
  var active=ZapretRoutes.Active(state);var upstream=ZapretRuntime.EngineProfiles(active,true);var ours=ZapretRuntime.EngineProfiles(active,false);
  original.WardogsAutoPause=true;var otherOriginal=new RouteList{Name="other original",Target="zapret",ZapretProfileId=p.Id,Text="other.example",MatchMode="addresses",OriginalEngine=true};state.Lists.Add(otherOriginal);var paused=ZapretRuntime.WardogsOriginalProfiles(ZapretRoutes.Active(state),new HashSet<string>{p.Id});Check(paused.Single().Settings.ScopeRules.Single().Id==otherOriginal.Id,"autopause removes only Wardogs route, preserves other original route in same profile");state.Lists.Remove(otherOriginal);original.WardogsAutoPause=false;
  Check(upstream.Length==1&&ours.Length==1&&upstream[0].Settings.ScopeRules.Single().Id==original.Id&&ours[0].Settings.ScopeRules.Single().Id==ordinary.Id,"same profile splits by route engine without rejecting adjacent Discord process rule");
  string upstreamArgs=runtime.BuildProfileArguments(upstream,catalog,Path.Combine(root,"split-original"));string oursArgs="--wf-raw-part=false "+ZapretRuntime.ExcludeOriginalScopes(runtime.BuildProfileArguments(ours,catalog,Path.Combine(root,"split-ours")),upstream,Path.Combine(root,"split-exclusions"));
  Check(!upstreamArgs.Contains("--mcrf-")&&oursArgs.Contains("--mcrf-apps="),"original engine never receives process flags; own engine retains them");
