  bool administrator;using(var identity=System.Security.Principal.WindowsIdentity.GetCurrent())administrator=new System.Security.Principal.WindowsPrincipal(identity).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);if(!administrator)Console.WriteLine("SKIP original EXE execution: administrator required");for(int i=administrator?0:1;i<2;i++){string args=i==0?upstreamArgs:oursArgs;string exe=i==0?Path.Combine(runtime.DirectoryPath,"winws.exe"):runtime.AppExecutable();string filter=Path.Combine(root,"split-"+i+".filter");using(var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(exe,args+" --wf-save="+ZapretRuntime.Quote(filter)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true,WorkingDirectory=Path.GetDirectoryName(exe)})){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(10000)){process.Kill();throw new Exception("split export timeout");}System.Threading.Tasks.Task.WaitAll(output,error);Check(process.ExitCode==0&&File.Exists(filter),"engine "+i+" accepts separate scoped configuration without network capture: "+error.Result);}}
  original.Text+="\napp:game.exe";bool rejected=false;try{ZapretRoutes.Validate(original,state.ZapretProfiles);}catch(InvalidOperationException){rejected=true;}Check(rejected,"process condition rejected only on marked original route");original.Text="game.example\n85.236.98.104/32";
  var json=new System.Web.Script.Serialization.JavaScriptSerializer();Check(json.Deserialize<RouteList>(json.Serialize(original)).OriginalEngine,"original route engine selection persists");
  var alternative=SteamGameTemplates.WardogsAlternative(catalog);var fields=RouteCompiler.Parse(alternative.Item2.Text);Check(fields["process_name"].Single()=="WardogsClient-Win64-Shipping.exe"&&fields["domain_suffix"].Count+fields["domain"].Count==7&&fields["ip_cidr"].Count==0,"Alternative contains exact process and seven deduplicated domains, no old IP pool");Check(alternative.Item2.Dns.Provider=="Google"&&alternative.Item2.Dns.Protocol=="UDP"&&alternative.Item2.GameTcpEnabled&&alternative.Item2.GameUdpEnabled&&alternative.Item2.MatchMode=="any","Alternative uses ALT11, TCP+UDP, Google UDP and OR matching");
  var archive=SteamGameTemplates.WardogsArchive(catalog);Check(archive.Item2.OriginalEngine&&archive.Item1.Settings.Strategy==catalog.First(s=>s.Family=="Flowseal"&&s.ShortName=="ALT9").Id&&!archive.Item2.GameUdpEnabled,"archive template is explicitly scoped ALT9 adaptation, not global /0 game interception");
  using(var dialog=new RouteDialog(original,new NetworkCore(new StateStore(root)),state.ZapretProfiles)){dialog.Show();Application.DoEvents();var toggle=Controls(dialog).OfType<GlassToggle>().Single(c=>c.Name=="routeOriginalEngine");var target=Controls(dialog).OfType<GlassPicker>().Single(c=>c.Name=="routeTarget");Check(toggle.Visible&&toggle.Checked,"Zapret route editor shows persisted original engine switch");target.SelectedIndex=1;Check(!toggle.Visible,"non-Zapret outputs hide original engine switch");target.SelectedIndex=4;Check(toggle.Visible,"switch returns for Zapret output");using(var bitmap=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(Point.Empty,dialog.Size));bitmap.Save(Path.Combine(root,"route-original-engine.png"));}dialog.Close();}
  var warpState=new ClientState{IndependentWarpOutputs=true,VpnEnabled=false,WarpEnabled=true,Mode="tun",DnsProvider="Системный",DnsProtocol="Системный"};var warp=Links.Read("[Interface]\nPrivateKey=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=\nAddress=172.16.0.2/32\n[Peer]\nPublicKey=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=\nEndpoint=162.159.192.1:2408").Single();warp.Link=warp.Link.Replace("PublicKey=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","PublicKey="+WarpScout.PeerPublicKey);warp.Name="WARP test";warpState.Servers.Add(warp);warpState.Lists.Add(new RouteList{Name="YouTube only",Text="youtube.com",MatchMode="addresses",Target=WarpOutputs.Tag(warp)});var configuration=new NetworkCore(new StateStore(root)).Build(warpState);var routing=(Dictionary<string,object>)configuration["route"];Check(Convert.ToString(routing["final"])=="direct"&&!json.Serialize(routing).Contains("chess.com"),"WARP-only YouTube route does not change default direct route or assign chess.com");Check(Convert.ToString(((Dictionary<string,object>)configuration["dns"])["final"])=="chosen","WARP does not replace shared DNS selection");
