 static void Check(bool value,string text){if(!value)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}
 static T Field<T>(object owner,string name){return (T)owner.GetType().GetField(name,Flags).GetValue(owner);}
 static IEnumerable<Control> Controls(Control root){return root.Controls.Cast<Control>().SelectMany(c=>new[]{c}.Concat(Controls(c)));}
 static void Reject(Action action,string label){try{action();}catch(FormatException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
 static void Pump(Func<bool> ready){var watch=System.Diagnostics.Stopwatch.StartNew();while(!ready()&&watch.ElapsedMilliseconds<7000){Application.DoEvents();System.Threading.Thread.Sleep(5);}if(!ready())throw new Exception("UI completion timeout");Application.DoEvents();}static void Page(MainForm form,string name){System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());form.GetType().GetMethod("ShowPage",Flags).Invoke(form,new object[]{name});for(int i=0;i<20;i++)Application.DoEvents();if(name=="routes")Pump(()=>Controls(form).Any(c=>c.Name=="routeTable"));if(name=="zapret")Pump(()=>!Controls(form).Any(c=>c.Name=="zapretLoading"));}
 static void Capture(MainForm form,string root,string name){Control target=Controls(form).FirstOrDefault(c=>c.Name=="mainSection")??(Control)form;using(var image=new Bitmap(target.Width,target.Height)){target.DrawToBitmap(image,new Rectangle(Point.Empty,target.Size));image.Save(Path.Combine(root,name+".png"));}}
